import { spawnSync } from "node:child_process"
import { chmodSync, existsSync, readFileSync, writeFileSync } from "node:fs"
import { homedir } from "node:os"
import { basename, dirname } from "node:path"
import { DotgenError } from "./errors.ts"
import { escapeValue } from "./escape.ts"
import type { Loader } from "./schema.ts"
import type { Entry, Scalar, WriteOptions, WriteResult } from "./types.ts"

export const envHeader = "# Generated by dotgen"

// Headers written by earlier versions, still recognized as generated files.
export const legacyHeaders = ["# Generado por dotgen", "// Generado por dotgen"]

export function tildePath(path: string): string {
	const home = homedir()
	return path === home || path.startsWith(`${home}/`) ? `~${path.slice(home.length)}` : path
}

const sensitiveName = /PASS|PWD|SECRET|TOKEN|KEY|CREDENTIAL|PRIVATE|DSN|CONNECTION/
// URL with credentials in the user part: `smtp://user:password@host`.
const credentialUrl = /[a-z][a-z0-9+.-]*:\/\/[^/@\s]*:[^/@\s]*@/i

// Sensitive by name or by value: a URI with a password is secret even if it's called `TRANSPORT_URI`.
export function isSensitive(name: string, value?: Scalar): boolean {
	return sensitiveName.test(name) || (typeof value === "string" && credentialUrl.test(value))
}

// What can be shown in the console: sensitive values only by length, to spot truncated values.
export function display(name: string, value: Scalar): string {
	const text = String(value)
	return isSensitive(name, value) ? `set (${text.length} chars)` : JSON.stringify(text)
}

// Contents of a target's environment file. `entries` is already sorted by name.
export function renderEnvFile(context: { entries: Entry[]; loader: Loader; project: string; env: string; source: string }): string {
	const { entries, loader, project, env, source } = context
	const lines = [
		`${envHeader} from ${tildePath(source)} (${project} / ${env}).`,
		"# Do not edit: changes are lost when regenerating.",
		...entries.map((entry) => `${entry.name}=${escapeValue(entry.name, entry.value, loader)}`)
	]
	return `${lines.join("\n")}\n`
}

// Writes `content` to `file` unless it exists without dotgen's header (and without `force`).
// With `dryRun` it runs the same checks but doesn't touch the disk.
export function writeGenerated(file: string, content: string, options: WriteOptions): WriteResult {
	const { header, mode, force = false, dryRun = false } = options
	let status: WriteResult["status"] = "created"
	if (existsSync(file)) {
		const current = readFileSync(file, "utf8")
		const generated = [header, ...legacyHeaders].some((prefix) => current.startsWith(prefix))
		if (!generated && !force) {
			throw new DotgenError(`${file} exists and wasn't generated by dotgen. Use --force to overwrite it.`)
		}
		status = current === content ? "unchanged" : "updated"
	}
	if (dryRun) return { file, status, written: false }
	if (status !== "unchanged") writeFileSync(file, content, mode === undefined ? undefined : { mode })
	// `mode` only applies on create, so it's also forced on existing files.
	if (mode !== undefined) chmodSync(file, mode)
	return { file, status, written: status !== "unchanged" }
}

// Warns if the file isn't ignored by git. Says nothing outside a repo.
export function gitignoreWarning(file: string): string | undefined {
	const result = spawnSync("git", ["check-ignore", "-q", basename(file)], { cwd: dirname(file) })
	if (result.status === 1) return `${file} isn't in .gitignore: it has values that shouldn't be committed.`
	return undefined
}
